1	import {
2	  MessageLikeEventContent_Tags,
3	  type NotificationClientInterface,
4	  NotificationEvent_Tags,
5	  type NotificationItem,
6	  NotificationProcessSetup,
7	  type NotificationSettingsInterface,
8	  NotificationStatus_Tags,
9	  TimelineEventType_Tags,
10	} from "@unomed/react-native-matrix-sdk";
11	import { MATRIX_ENDPOINTS, SygnalURL } from "../../matrix-client/const";
12	import { MatrixCore } from "../../matrix-client/services/MatrixCore";
13	
14	const APP_ID = "com.prototyp.cloak";
15	const VOIP_APP_ID = "com.prototyp.cloak.ios.voip";
16	
17	export class MatrixNotificationService {
18	  private static notificationClient: NotificationClientInterface | null = null;
19	
20	  private static isRtcNotificationExpired = (
21	    item: NotificationItem,
22	  ): boolean => {
23	    if (item.event.tag !== NotificationEvent_Tags.Timeline) return false;
24	
25	    const eventType = item.event.inner.event.eventType();
26	    if (eventType.tag !== TimelineEventType_Tags.MessageLike) return false;
27	
28	    const content = eventType.inner.content;
29	    if (content.tag !== MessageLikeEventContent_Tags.RtcNotification) {
30	      return false;
31	    }
32	
33	    const expirationTs = content.inner?.expirationTs;
34	    if (expirationTs === undefined || expirationTs === null) return false;
35	
36	    const nowMs = Date.now();
37	
38	    if (typeof expirationTs === "bigint") {
39	      return BigInt(nowMs) >= expirationTs;
40	    }
41	
42	    if (typeof expirationTs === "number") {
43	      return nowMs >= expirationTs;
44	    }
45	
46	    if (typeof expirationTs === "string") {
47	      try {
48	        return BigInt(nowMs) >= BigInt(expirationTs);
49	      } catch {
50	        return false;
51	      }
52	    }
53	
54	    return false;
55	  };
56	
57	  public static getNotificationSettings =
58	    async (): Promise<NotificationSettingsInterface> => {
59	      const client = MatrixCore.getClient();
60	      return await client.getNotificationSettings();
61	    };
62	
63	  public static isNotificationExpiredCall = (
64	    item: NotificationItem,
65	  ): boolean => {
66	    return this.isRtcNotificationExpired(item);
67	  };
68	
69	  public static getNotificationClient = () => this.notificationClient;
70	
71	  public static ensureNotificationClient =
72	    async (): Promise<NotificationClientInterface | null> => {
73	      if (this.notificationClient) return this.notificationClient;
74	      if (!MatrixCore.instance) return null;
75	
76	      try {
77	        this.notificationClient = await MatrixCore.instance.notificationClient(
78	          new NotificationProcessSetup.MultipleProcesses(),
79	        );
80	        return this.notificationClient;
81	      } catch (error) {
82	        console.warn("Failed to create notification client:", error);
83	        return null;
84	      }
85	    };
86	
87	  public static initNotificationClientForBackground =
88	    async (): Promise<void> => {
89	      const client = MatrixCore.getClient();
90	      this.notificationClient = await client.notificationClient(
91	        new NotificationProcessSetup.MultipleProcesses(),
92	      );
93	    };
94	
95	  public static getNotificationContent = async (
96	    roomId: string,
97	    eventId: string,
98	  ): Promise<NotificationItem | null> => {
99	    try {
100	      if (!this.notificationClient) {
101	        console.warn("Notification client not initialized");
102	        return null;
103	      }
104	
105	      const status = await this.notificationClient.getNotification(
106	        roomId,
107	        eventId,
108	      );
109	
110	      if (status.tag !== NotificationStatus_Tags.Event) {
111	        console.warn("Notification status:", status.tag);
112	        return null;
113	      }
114	
115	      const item = status.inner.item;
116	      if (this.isRtcNotificationExpired(item)) return null;
117	
118	      return item;
119	    } catch (error) {
120	      console.warn("Failed to get notification content:", error);
121	      return null;
122	    }
123	  };
124	
125	  /**
126	   * Fetches notification status once and returns both the decoded item and
127	   * whether the SDK filtered it out — so callers avoid multiple round-trips.
128	   */
129	  public static getNotificationResult = async (
130	    roomId: string,
131	    eventId: string,
132	  ): Promise<
133	    | { item: NotificationItem; filteredOut: false }
134	    | { item: null; filteredOut: boolean }
135	  > => {
136	    if (!this.notificationClient) return { item: null, filteredOut: false };
137	    try {
138	      const status = await this.notificationClient.getNotification(
139	        roomId,
140	        eventId,
141	      );
142	      if (status.tag === NotificationStatus_Tags.EventFilteredOut) {
143	        return { item: null, filteredOut: true };
144	      }
145	      if (status.tag !== NotificationStatus_Tags.Event) {
146	        return { item: null, filteredOut: false };
147	      }
148	      const item = status.inner.item;
149	      if (this.isRtcNotificationExpired(item)) {
150	        return { item: null, filteredOut: false };
151	      }
152	      return { item, filteredOut: false };
153	    } catch {
154	      return { item: null, filteredOut: false };
155	    }
156	  };
157	
158	  /**
159	   * Returns true if the event was filtered out by the user's push rules.
160	   * This means the SDK explicitly determined no notification should be shown.
161	   */
162	  public static isNotificationFilteredOut = async (
163	    roomId: string,
164	    eventId: string,
165	  ): Promise<boolean> => {
166	    try {
167	      if (!this.notificationClient) return false;
168	      const status = await this.notificationClient.getNotification(
169	        roomId,
170	        eventId,
171	      );
172	      return status.tag === NotificationStatus_Tags.EventFilteredOut;
173	    } catch {
174	      return false;
175	    }
176	  };
177	
178	  public static getPushers = async () => {
179	    const client = MatrixCore.getClient();
180	    const session = client.session();
181	    if (!session) throw new Error("No active session");
182	
