import {
  getMessaging,
  setBackgroundMessageHandler,
} from "@react-native-firebase/messaging";
import { Buffer } from "buffer";
import { EventEmitter } from "events";
import {
  NotifeeService,
  PushNotificationsService,
} from "modules/push-notifications/service";
import { useEffect, useState } from "react";
import { AppRegistry, AppState } from "react-native";
import "react-native-get-random-values";
import "react-native-url-polyfill/auto";
import { App } from "./App";
import { name as appName } from "./app.json";
import "./src/polyfills/promise-with-resolvers";

NotifeeService.init().catch((error) => {
  console.error("Failed to initialize NotifeeService:", error);
});

NotifeeService.registerBackgroundEventHandler();

setBackgroundMessageHandler(getMessaging(), async (remoteMessage) => {
  console.log("Background message received:", remoteMessage);
  try {
    await PushNotificationsService.handleBackgroundMessage(remoteMessage);
  } catch (error) {
    console.error("Failed to handle background message:", error);
  }
});

if (typeof global.EventEmitter === "undefined") {
  global.EventEmitter = EventEmitter;
}

if (typeof global.Buffer === "undefined") {
  global.Buffer = Buffer;
}

function HeadlessCheck({ isHeadless }) {
  // When launched in background (isHeadless === true), render nothing until the
  // user actually opens the app. Without this, the process stays alive with a
  // blank React view, the LaunchScreen disappears and reveals nothing.
  const [active, setActive] = useState(!isHeadless);

  useEffect(() => {
    if (!isHeadless) return;
    const sub = AppState.addEventListener("change", (state) => {
      if (state === "active") setActive(true);
    });
    return () => sub.remove();
  }, [isHeadless]);

  if (!active) return null;
  return <App />;
}

AppRegistry.registerComponent(appName, () => HeadlessCheck);

