import UIKit
import React
import React_RCTAppDelegate
import ReactAppDependencyProvider
import Firebase
import RNFBMessaging
import RNCallKeep
import PushKit

@main
class AppDelegate: UIResponder, UIApplicationDelegate {
  var window: UIWindow?

  var reactNativeDelegate: ReactNativeDelegate?
  var reactNativeFactory: RCTReactNativeFactory?

  private var voipRegistry: PKPushRegistry?

  func application(
    _ application: UIApplication,
    didFinishLaunchingWithOptions launchOptions: [UIApplication.LaunchOptionsKey: Any]? = nil
  ) -> Bool {
    FirebaseApp.configure()

    let delegate = ReactNativeDelegate()
    let factory = RCTReactNativeFactory(delegate: delegate)
    delegate.dependencyProvider = RCTAppDependencyProvider()

    reactNativeDelegate = delegate
    reactNativeFactory = factory

    window = UIWindow(frame: UIScreen.main.bounds)

    let initialProps = RNFBMessagingModule.addCustomProps(toUserProps: nil, withLaunchOptions: launchOptions)

    factory.startReactNative(
      withModuleName: "cloakanddagger",
      in: window,
      initialProperties: initialProps,
      launchOptions: launchOptions
    )

    setupVoIPPushRegistry()

    return true
  }

  func application(
    _ application: UIApplication,
    continue userActivity: NSUserActivity,
    restorationHandler: @escaping ([UIUserActivityRestoring]?) -> Void
  ) -> Bool {
    return RNCallKeep.application(application, continue: userActivity, restorationHandler: { restorableObjects in
      restorationHandler(restorableObjects as? [UIUserActivityRestoring])
    })
  }

  private func setupVoIPPushRegistry() {
    let registry = PKPushRegistry(queue: .main)
    registry.delegate = self
    registry.desiredPushTypes = [.voIP]
    voipRegistry = registry
  }
}

extension AppDelegate: PKPushRegistryDelegate {
  func pushRegistry(_ registry: PKPushRegistry, didUpdate pushCredentials: PKPushCredentials, for type: PKPushType) {
    guard type == .voIP else { return }
    let token = pushCredentials.token.map { String(format: "%02x", $0) }.joined()
    VoIPPushModule.emitToken(token)
  }

  func pushRegistry(
    _ registry: PKPushRegistry,
    didReceiveIncomingPushWith payload: PKPushPayload,
    for type: PKPushType,
    completion: @escaping () -> Void
  ) {
    guard type == .voIP else { completion(); return }

    let dict = payload.dictionaryPayload

    // Support both flat payload and nested under "notification"
    let nested = dict["notification"] as? [String: Any]
    let roomId = dict["room_id"] as? String
      ?? nested?["room_id"] as? String
      ?? "unknown"
    let callerName = dict["sender_display_name"] as? String
      ?? nested?["sender_display_name"] as? String
      ?? dict["sender"] as? String
      ?? nested?["sender"] as? String
      ?? "Unknown"
    let callUUID = UUID().uuidString

    // Store call info so JS can retrieve roomId/roomName after a cold-start answer
    UserDefaults.standard.set(roomId, forKey: "pendingCallRoomId")
    UserDefaults.standard.set(callerName, forKey: "pendingCallRoomName")

    // MUST call reportNewIncomingCall synchronously — iOS will kill the app otherwise
    RNCallKeep.reportNewIncomingCall(
      callUUID,
      handle: roomId,
      handleType: "generic",
      hasVideo: true,
      localizedCallerName: callerName,
      supportsHolding: false,
      supportsDTMF: false,
      supportsGrouping: false,
      supportsUngrouping: false,
      fromPushKit: true,
      payload: dict,
      withCompletionHandler: completion
    )
  }

  func pushRegistry(_ registry: PKPushRegistry, didInvalidatePushTokenFor type: PKPushType) {
    // Nothing to do — the token will be refreshed on next launch
  }
}

class ReactNativeDelegate: RCTDefaultReactNativeFactoryDelegate {
  override func sourceURL(for bridge: RCTBridge) -> URL? {
    self.bundleURL()
  }

  override func bundleURL() -> URL? {
#if DEBUG
    RCTBundleURLProvider.sharedSettings().jsBundleURL(forBundleRoot: "index")
#else
    Bundle.main.url(forResource: "main", withExtension: "jsbundle")
#endif
  }
}

